using LigaVolley.Domain.MatchSheets;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace LigaVolley.Infrastructure.Persistence.Configurations;
internal sealed class MatchSheetConfiguration:IEntityTypeConfiguration<MatchSheet>{public void Configure(EntityTypeBuilder<MatchSheet>b){b.ToTable("MATCH_SHEET","dbo",t=>{t.HasCheckConstraint("CK_MATCH_SHEET_status","[status] IN ('OPEN','IN_PROGRESS','SUSPENDED','CLOSED','CANCELLED')");t.HasCheckConstraint("CK_MATCH_SHEET_sets","[home_sets] BETWEEN 0 AND 3 AND [away_sets] BETWEEN 0 AND 3");});b.HasKey(x=>x.MatchSheetId);b.Property(x=>x.MatchSheetId).HasColumnName("match_sheet_id").UseIdentityColumn();b.Property(x=>x.SheetUuid).HasColumnName("sheet_uuid");b.Property(x=>x.MatchId).HasColumnName("match_id");b.Property(x=>x.Status).AsSql("status",20);b.Property(x=>x.OpenedAt).HasColumnName("opened_at");b.Property(x=>x.StartedAt).HasColumnName("started_at");b.Property(x=>x.EndedAt).HasColumnName("ended_at");b.Property(x=>x.HomeSets).HasColumnName("home_sets");b.Property(x=>x.AwaySets).HasColumnName("away_sets");b.Property(x=>x.WinnerTeamEntryId).HasColumnName("winner_team_entry_id");b.Property(x=>x.TrackSubstitutions).HasColumnName("track_substitutions").HasDefaultValue(true);b.Property(x=>x.TrackLiberoReplacements).HasColumnName("track_libero_replacements").HasDefaultValue(true);b.HasOne(x=>x.Match).WithOne().HasForeignKey<MatchSheet>(x=>x.MatchId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>x.MatchId).IsUnique().HasDatabaseName("UQ_MATCH_SHEET_match");b.HasIndex(x=>x.SheetUuid).IsUnique().HasDatabaseName("UQ_MATCH_SHEET_uuid");}}
internal sealed class MatchTeamConfiguration:IEntityTypeConfiguration<MatchTeam>{public void Configure(EntityTypeBuilder<MatchTeam>b){b.ToTable("MATCH_TEAM","dbo");b.HasKey(x=>x.MatchTeamId);b.Property(x=>x.MatchTeamId).HasColumnName("match_team_id").UseIdentityColumn();b.Property(x=>x.MatchTeamUuid).HasColumnName("match_team_uuid");b.Property(x=>x.MatchSheetId).HasColumnName("match_sheet_id");b.Property(x=>x.TeamEntryId).HasColumnName("team_entry_id");b.Property(x=>x.CompetitionRosterId).HasColumnName("competition_roster_id");b.Property(x=>x.Side).AsSql("side",10);b.HasOne(x=>x.MatchSheet).WithMany(x=>x.Teams).HasForeignKey(x=>x.MatchSheetId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.TeamEntry).WithMany().HasForeignKey(x=>x.TeamEntryId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.CompetitionRoster).WithMany().HasForeignKey(x=>x.CompetitionRosterId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.MatchSheetId,x.Side}).IsUnique();b.HasIndex(x=>x.MatchTeamUuid).IsUnique();}}
internal sealed class MatchPlayerConfiguration:IEntityTypeConfiguration<MatchPlayer>{public void Configure(EntityTypeBuilder<MatchPlayer>b){b.ToTable("MATCH_PLAYER","dbo");b.HasKey(x=>x.MatchPlayerId);b.Property(x=>x.MatchPlayerId).HasColumnName("match_player_id").UseIdentityColumn();b.Property(x=>x.MatchPlayerUuid).HasColumnName("match_player_uuid");b.Property(x=>x.MatchTeamId).HasColumnName("match_team_id");b.Property(x=>x.CompetitionRosterPlayerId).HasColumnName("competition_roster_player_id");b.Property(x=>x.JerseyNumber).HasColumnName("jersey_number");b.Property(x=>x.IsMatchCaptain).HasColumnName("is_match_captain");b.Property(x=>x.Status).AsSql("status",20);b.HasOne(x=>x.MatchTeam).WithMany(x=>x.Players).HasForeignKey(x=>x.MatchTeamId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.CompetitionRosterPlayer).WithMany().HasForeignKey(x=>x.CompetitionRosterPlayerId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.MatchTeamId,x.CompetitionRosterPlayerId}).IsUnique();b.HasIndex(x=>new{x.MatchTeamId,x.JerseyNumber}).IsUnique().HasFilter("[jersey_number] IS NOT NULL");b.HasIndex(x=>x.MatchPlayerUuid).IsUnique();b.HasIndex(x=>x.MatchTeamId).IsUnique().HasFilter("[is_match_captain] = 1").HasDatabaseName("UX_MATCH_PLAYER_captain");}}
internal sealed class MatchTeamStaffConfiguration:IEntityTypeConfiguration<MatchTeamStaff>{public void Configure(EntityTypeBuilder<MatchTeamStaff>b){b.ToTable("MATCH_TEAM_STAFF","dbo");b.HasKey(x=>x.MatchTeamStaffId);b.Property(x=>x.MatchTeamStaffId).HasColumnName("match_team_staff_id").UseIdentityColumn();b.Property(x=>x.MatchTeamStaffUuid).HasColumnName("match_team_staff_uuid");b.Property(x=>x.MatchTeamId).HasColumnName("match_team_id");b.Property(x=>x.CompetitionRosterStaffId).HasColumnName("competition_roster_staff_id");b.Property(x=>x.Status).AsSql("status",20);b.HasOne(x=>x.MatchTeam).WithMany(x=>x.Staff).HasForeignKey(x=>x.MatchTeamId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.CompetitionRosterStaff).WithMany().HasForeignKey(x=>x.CompetitionRosterStaffId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.MatchTeamId,x.CompetitionRosterStaffId}).IsUnique();b.HasIndex(x=>x.MatchTeamStaffUuid).IsUnique();}}
internal sealed class MatchLiberoConfiguration:IEntityTypeConfiguration<MatchLibero>{public void Configure(EntityTypeBuilder<MatchLibero>b){b.ToTable("MATCH_LIBERO","dbo");b.HasKey(x=>x.MatchLiberoId);b.Property(x=>x.MatchLiberoId).HasColumnName("match_libero_id").UseIdentityColumn();b.Property(x=>x.MatchLiberoUuid).HasColumnName("match_libero_uuid");b.Property(x=>x.MatchTeamId).HasColumnName("match_team_id");b.Property(x=>x.MatchPlayerId).HasColumnName("match_player_id");b.Property(x=>x.LiberoOrder).HasColumnName("libero_order");b.HasOne(x=>x.MatchTeam).WithMany(x=>x.Liberos).HasForeignKey(x=>x.MatchTeamId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.MatchPlayer).WithMany().HasForeignKey(x=>x.MatchPlayerId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>new{x.MatchTeamId,x.MatchPlayerId}).IsUnique();b.HasIndex(x=>new{x.MatchTeamId,x.LiberoOrder}).IsUnique();b.HasIndex(x=>x.MatchLiberoUuid).IsUnique();}}
internal sealed class MatchSheetSessionConfiguration:IEntityTypeConfiguration<MatchSheetSession>{public void Configure(EntityTypeBuilder<MatchSheetSession>b){b.ToTable("MATCH_SHEET_SESSION","dbo");b.HasKey(x=>x.MatchSheetSessionId);b.Property(x=>x.MatchSheetSessionId).HasColumnName("match_sheet_session_id").UseIdentityColumn();b.Property(x=>x.SessionUuid).HasColumnName("session_uuid");b.Property(x=>x.MatchSheetId).HasColumnName("match_sheet_id");b.Property(x=>x.MatchOfficialId).HasColumnName("match_official_id");b.Property(x=>x.DeviceId).HasColumnName("device_id").HasMaxLength(100);b.Property(x=>x.Status).AsSql("status",20);b.Property(x=>x.StartedAt).HasColumnName("started_at");b.Property(x=>x.EndedAt).HasColumnName("ended_at");b.HasOne(x=>x.MatchSheet).WithMany(x=>x.Sessions).HasForeignKey(x=>x.MatchSheetId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.MatchOfficial).WithMany().HasForeignKey(x=>x.MatchOfficialId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>x.SessionUuid).IsUnique();b.HasIndex(x=>x.MatchSheetId).IsUnique().HasFilter("[status] = 'ACTIVE'").HasDatabaseName("UX_MATCH_SHEET_SESSION_active");}}
internal sealed class MatchSheetAuditConfiguration:IEntityTypeConfiguration<MatchSheetAudit>{public void Configure(EntityTypeBuilder<MatchSheetAudit>b){b.ToTable("MATCH_SHEET_AUDIT","dbo");b.HasKey(x=>x.MatchSheetAuditId);b.Property(x=>x.MatchSheetAuditId).HasColumnName("match_sheet_audit_id").UseIdentityColumn();b.Property(x=>x.AuditUuid).HasColumnName("audit_uuid");b.Property(x=>x.MatchSheetId).HasColumnName("match_sheet_id");b.Property(x=>x.MatchSheetSessionId).HasColumnName("match_sheet_session_id");b.Property(x=>x.Type).AsSql("event_type",30);b.Property(x=>x.ClientRequestId).HasColumnName("client_request_id");b.Property(x=>x.OccurredAt).HasColumnName("occurred_at");b.HasOne(x=>x.MatchSheet).WithMany(x=>x.Audits).HasForeignKey(x=>x.MatchSheetId).OnDelete(DeleteBehavior.Restrict);b.HasOne(x=>x.Session).WithMany().HasForeignKey(x=>x.MatchSheetSessionId).OnDelete(DeleteBehavior.Restrict);b.HasIndex(x=>x.AuditUuid).IsUnique();b.HasIndex(x=>new{x.MatchSheetId,x.ClientRequestId}).IsUnique();}}
